package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructMapType_TriageGen1Test {

    @Test
    public void testConstructMapType_WithProperties() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // The method logic: if (mapClass == Properties.class) { kt = vt = CORE_TYPE_STRING; }
        // We test this specific branch.
        MapType result = typeFactory.constructMapType(Properties.class, Object.class, Object.class);

        Assert.assertNotNull("Resulting MapType should not be null", result);
        Assert.assertEquals("Map class should be Properties", Properties.class, result.rawClass());

        // For Properties, Jackson maps both key and value to String (CORE_TYPE_STRING)
        JavaType expectedKeyType = typeFactory.constructType(String.class);
        JavaType expectedValueType = typeFactory.constructType(String.class);

        Assert.assertEquals("Key type for Properties must be String", expectedKeyType, result.getKeyType());
        Assert.assertEquals("Value type for Properties must be String", expectedValueType, result.getValueType());
    }

    @Test
    public void testConstructMapType_WithHashMap() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // The method logic: else { kt = _fromClass(...); vt = _fromClass(...); }
        // We test the general branch using HashMap with Integer keys and String values.
        Class<? extends Map> mapClass = HashMap.class;
        Class<?> keyClass = Integer.class;
        Class<?> valueClass = String.class;

        MapType result = typeFactory.constructMapType(mapClass, keyClass, valueClass);

        Assert.assertNotNull("Resulting MapType should not be null", result);
        Assert.assertEquals("Map class should be HashMap", mapClass, result.rawClass());

        JavaType expectedKeyType = typeFactory.constructType(Integer.class);
        JavaType expectedValueType = typeFactory.constructType(String.class);

        Assert.assertEquals("Key type should match provided keyClass", expectedKeyType, result.getKeyType());
        Assert.assertEquals("Value type should match provided valueClass", expectedValueType, result.getValueType());
    }

    @Test
    public void testConstructMapType_WithDifferentMapImplementation() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test with TreeMap to ensure it's not hardcoded to HashMap
        Class<? extends Map> mapClass = java.util.TreeMap.class;
        Class<?> keyClass = String.class;
        Class<?> valueClass = Double.class;

        MapType result = typeFactory.constructMapType(mapClass, keyClass, valueClass);

        Assert.assertNotNull(result);
        Assert.assertEquals(mapClass, result.rawClass());
        Assert.assertEquals(typeFactory.constructType(String.class), result.getKeyType());
        Assert.assertEquals(typeFactory.constructType(Double.class), result.getValueType());
    }

    @Test
    public void testConstructMapType_WithPrimitiveWrapper() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test with boolean and long to ensure _fromClass handles various types
        MapType result = typeFactory.constructMapType(HashMap.class, Boolean.class, Long.class);

        Assert.assertEquals(typeFactory.constructType(Boolean.class), result.getKeyType());
        Assert.assertEquals(typeFactory.constructType(Long.class), result.getValueType());
    }
}
